/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Sealed traits and case classes for type-safe enumerations
 * - Generic types with variance annotations
 * - Option types for null safety
 * - Pattern matching for type dispatch
 * - Immutable data structures by default
 * - Type classes for ad-hoc polymorphism
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import java.nio.charset.{Charset, StandardCharsets}
import scala.util.{Try, Success, Failure}
import scala.collection.immutable.Map

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 *
 * @param value The string value of the token
 * @param tokenType The type of the token
 * @param metadata Additional metadata as a map
 */
case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /**
   * Return new token with additional metadata.
   */
  def withMetadata(entries: (String, Any)*): Token = {
    copy(metadata = metadata ++ entries.toMap)
  }
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 * Uses var for mutable state management.
 */
class MutableTokenBatch {
  private var tokens: List[Token] = List.empty
  private var _processed: Boolean = false

  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens = tokens :+ token
  }

  def markProcessed(): Unit = {
    _processed = true
  }

  def getTokens: List[Token] = tokens
  def isProcessed: Boolean = _processed
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 * Using +T for covariance.
 */
class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Vector[T] = _items

  def mapTokens[B](func: T => B): List[B] = {
    _items.map(func).toList
  }
}

/**
 * Contravariant sink - can accept supertypes.
 * Using -T for contravariance.
 */
class TokenSink[-T] {
  private var _received: List[Any] = List.empty

  def receive(item: T): Unit = {
    _received = _received :+ item
  }

  def drain(): List[Any] = {
    val result = _received
    _received = List.empty
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 * No variance annotation means invariance.
 */
class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Protocol Definitions (Structural Typing via Traits)
// ============================================================================

/**
 * Any object that can be converted to a token string.
 */
trait Tokenizable {
  def toToken: String
}

/**
 * Any object with a length.
 */
trait HasLength {
  def length: Int
}

/**
 * Contravariant processor that consumes tokens.
 */
trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[T] {
  /**
   * Convert value to token.
   */
  def tokenize(value: T): Token

  /**
   * Lazy tokenization of multiple values using Iterator.
   */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

/**
 * Tokenizer for string and byte array types.
 *
 * @param encoding Character encoding for byte arrays
 * @param normalizer Optional normalization function
 */
class StringTokenizer(
  encoding: Charset = StandardCharsets.UTF_8,
  normalizer: Option[String => String] = None
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(str) => str
      case Right(bytes) => new String(bytes, encoding)
    }

    val normalized = normalizer.map(_(strValue)).getOrElse(strValue)
    Token(normalized, TokenType.STRING)
  }
}

/**
 * Type class for numeric types to provide string conversion.
 */
trait Numeric[T] {
  def toString(value: T, precision: Int): String
  def typeName: String
}

object Numeric {
  implicit val intNumeric: Numeric[Int] = new Numeric[Int] {
    def toString(value: Int, precision: Int): String = value.toString
    def typeName: String = "Int"
  }

  implicit val longNumeric: Numeric[Long] = new Numeric[Long] {
    def toString(value: Long, precision: Int): String = value.toString
    def typeName: String = "Long"
  }

  implicit val doubleNumeric: Numeric[Double] = new Numeric[Double] {
    def toString(value: Double, precision: Int): String = f"$value%.${precision}f"
    def typeName: String = "Double"
  }

  implicit val floatNumeric: Numeric[Float] = new Numeric[Float] {
    def toString(value: Float, precision: Int): String = f"$value%.${precision}f"
    def typeName: String = "Float"
  }

  implicit val bigDecimalNumeric: Numeric[BigDecimal] = new Numeric[BigDecimal] {
    def toString(value: BigDecimal, precision: Int): String =
      value.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString
    def typeName: String = "BigDecimal"
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 * Uses type class pattern for ad-hoc polymorphism.
 *
 * @param precision Decimal precision for floating point numbers
 * @param formatOptions Additional formatting options
 */
class NumericTokenizer[T: Numeric](
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[T] {

  private val numericInstance = implicitly[Numeric[T]]

  def tokenize(value: T): Token = {
    val strValue = numericInstance.toString(value, precision)
    Token(
      strValue,
      TokenType.NUMERIC,
      Map("original_type" -> numericInstance.typeName)
    )
  }
}

/**
 * Tokenizer for date/time types.
 *
 * @param formatStr Optional custom format string
 */
class TemporalTokenizer(formatStr: Option[String] = None)
  extends BaseTokenizer[Either[LocalDateTime, LocalDate]] {

  private val isoFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  def tokenize(value: Either[LocalDateTime, LocalDate]): Token = {
    val (str, defaultFormatter) = value match {
      case Left(dateTime) =>
        val formatter = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(isoFormat)
        (dateTime.format(formatter), isoFormat)
      case Right(date) =>
        val formatter = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(dateFormat)
        (date.format(formatter), dateFormat)
    }

    Token(str, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Advanced: Union Types and Pattern Matching
// ============================================================================

/**
 * Tokenizer that handles multiple types with pattern matching.
 * Demonstrates Scala's pattern matching as an alternative to Python's overloading.
 */
class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericIntTokenizer = new NumericTokenizer[Int]()
  private val numericDoubleTokenizer = new NumericTokenizer[Double]()
  private val numericBigDecimalTokenizer = new NumericTokenizer[BigDecimal]()
  private val temporalTokenizer = new TemporalTokenizer()

  /**
   * Dispatch to appropriate tokenizer based on runtime type.
   * Uses pattern matching instead of overloading.
   */
  def tokenize(value: Any): Token = value match {
    case null =>
      Token("NULL", TokenType.NULL)

    case t: Tokenizable =>
      Token(t.toToken, TokenType.STRUCTURED)

    case s: String =>
      stringTokenizer.tokenize(Left(s))

    case bytes: Array[Byte] =>
      stringTokenizer.tokenize(Right(bytes))

    case i: Int =>
      numericIntTokenizer.tokenize(i)

    case d: Double =>
      numericDoubleTokenizer.tokenize(d)

    case f: Float =>
      numericDoubleTokenizer.tokenize(f.toDouble)

    case bd: BigDecimal =>
      numericBigDecimalTokenizer.tokenize(bd)

    case dt: LocalDateTime =>
      temporalTokenizer.tokenize(Left(dt))

    case d: LocalDate =>
      temporalTokenizer.tokenize(Right(d))

    case other =>
      // Fallback: use toString
      Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 * Uses immutable Map for registry and mutable buffer for handlers.
 */
class TokenRegistry[T] {
  private var _registry: Map[String, TokenContainer[T]] = Map.empty
  private var _handlers: List[T => Option[Token]] = List.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    _registry = _registry + (key -> container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    _handlers = _handlers :+ handler
  }

  def process(key: String): List[Option[Token]] = {
    _registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.iterator
            .map(_(item))
            .find(_.isDefined)
            .getOrElse(None)
        }.toList
    }
  }
}

// ============================================================================
// Functor and Monad Patterns
// ============================================================================

/**
 * Functor for tokens.
 * Scala supports proper higher-kinded types with type constructors.
